import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];
const REQUEST_TYPES = ['지출', '구매'];
// 가정: 집행액은 결재 상신 이후(결재대기·진행중·승인·완료)인 품의서 금액의 합계로 본다.
// 가정: 상신 가능한 상태는 '기안' 하나뿐이다.
// 가정: 상신용 결재양식은 사용 중이고 연계 결재인 첫 양식을 쓴다.
// 가정: 결재문서 문서번호는 품의서 문서번호를 그대로 쓴다.
const LINKED_TYPE = 'purchase_request';

function toInt(v: unknown): number | null {
  if (typeof v === 'number' && Number.isInteger(v)) return v;
  if (typeof v === 'string' && /^\d+$/.test(v)) return Number(v);
  return null;
}

function toAmount(v: unknown): number | null {
  if (typeof v === 'number' && Number.isFinite(v)) return v;
  if (typeof v === 'string' && /^\d+(\.\d{1,2})?$/.test(v)) return Number(v);
  return null;
}

function pageParams(q: Record<string, unknown>): { page: number; size: number } {
  const page = q['page'] === undefined || q['page'] === '' ? 0 : toInt(q['page']);
  const size = q['size'] === undefined || q['size'] === '' ? DEFAULT_SIZE : toInt(q['size']);
  if (page === null || size === null || size < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
  }
  return { page, size: Math.min(size, MAX_SIZE) };
}

async function balanceOf(db: any, projectId: number, budgetItemId: number): Promise<number> {
  const rows = await db.query(
    `SELECT
       COALESCE((SELECT SUM(e.amount) FROM exec_budget e
         JOIN main_budget m ON m.main_budget_id = e.main_budget_id
         WHERE m.project_id = CAST(:projectId AS bigint)
           AND m.budget_item_id = CAST(:budgetItemId AS bigint)), 0) AS "execBudgetAmount",
       COALESCE((SELECT SUM(c.carryover_amount) FROM budget_carryover c
         WHERE c.project_id = CAST(:projectId AS bigint)
           AND c.budget_item_id = CAST(:budgetItemId AS bigint)), 0) AS "carryoverAmount",
       COALESCE((SELECT SUM(p.amount) FROM purchase_request p
         WHERE p.project_id = CAST(:projectId AS bigint)
           AND p.budget_item_id = CAST(:budgetItemId AS bigint)
           AND p.approval_status IN ('결재대기', '진행중', '승인', '완료')), 0) AS "executedAmount"`,
    { projectId, budgetItemId },
  );
  const r = rows[0];
  return Number(r.execBudgetAmount) + Number(r.carryoverAmount) - Number(r.executedAmount);
}

@Controller('api/v1')
export class FnSfr00401Controller {
  @Post('/purchase-requests')
  @HttpCode(200)
  async createPurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const data = checks.inputOf(req.body);
    const title = data['title'];
    if (typeof title !== 'string' || title.trim() === '' || title.length > 200) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 제목을 200자 이내로 입력하세요.');
    }
    const requestType = data['requestType'];
    if (typeof requestType !== 'string' || !REQUEST_TYPES.includes(requestType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 유형은 지출 또는 구매여야 합니다.');
    }
    const projectId = toInt(data['projectId']);
    if (projectId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트를 선택하세요.');
    }
    const budgetItemId = toInt(data['budgetItemId']);
    if (budgetItemId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '예산과목을 선택하세요.');
    }
    const amount = toAmount(data['amount']);
    if (amount === null || amount <= 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 금액은 0보다 큰 숫자여야 합니다.');
    }
    const reason = data['reason'];
    if (typeof reason !== 'string' || reason.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의 사유를 입력하세요.');
    }
    const inspection = data['assetInspectionRequired'];
    if (inspection !== undefined && inspection !== null && typeof inspection !== 'boolean') {
      throw new ApiError(400, 'VALIDATION_FAILED', '자산 검수 여부 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const projects = await db.query(
        'SELECT project_id FROM project WHERE project_id = CAST(:projectId AS bigint)',
        { projectId },
      );
      if (projects.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '프로젝트를 찾을 수 없습니다.');
      }
      const items = await db.query(
        'SELECT budget_item_id FROM budget_item WHERE budget_item_id = CAST(:budgetItemId AS bigint)',
        { budgetItemId },
      );
      if (items.length === 0) {
        throw new ApiError(404, 'NOT_FOUND', '예산과목을 찾을 수 없습니다.');
      }
      const balance = await balanceOf(db, projectId, budgetItemId);
      if (amount > balance) {
        throw new ApiError(422, 'AMOUNT_EXCEEDS_BUDGET_BALANCE', '품의 금액이 예산잔액을 초과했습니다.');
      }
      const inserted = await db.query(
        `INSERT INTO purchase_request (
           title, request_type, project_id, budget_item_id, requester_id, amount, reason,
           approval_status, asset_inspection_required, created_at, updated_at
         ) VALUES (
           :title, :requestType, CAST(:projectId AS bigint), CAST(:budgetItemId AS bigint),
           CAST(:userId AS bigint), CAST(:amount AS numeric), :reason,
           '기안', :inspection, now(), now()
         ) RETURNING purchase_request_id AS "purchaseRequestId"`,
        {
          title: title.trim(),
          requestType,
          projectId,
          budgetItemId,
          userId: user.id,
          amount,
          reason,
          inspection: inspection === true,
        },
      );
      const rows = await db.query(
        `UPDATE purchase_request
           SET document_no = 'PR-' || to_char(now(), 'YYYY') || '-' || lpad(CAST(purchase_request_id AS text), 6, '0'),
               updated_at = now()
         WHERE purchase_request_id = CAST(:id AS bigint)
         RETURNING purchase_request_id AS "purchaseRequestId", document_no AS "documentNo", approval_status AS "approvalStatus"`,
        { id: inserted[0].purchaseRequestId },
      );
      return rows[0];
    });
  }

  @Get('/purchase-requests')
  async listPurchaseRequests(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const { page, size } = pageParams(q);
    let projectId: number | null = null;
    if (q['projectId'] !== undefined && q['projectId'] !== '') {
      projectId = toInt(q['projectId']);
      if (projectId === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트 값이 올바르지 않습니다.');
      }
    }
    let approvalStatus: string | null = null;
    if (q['approvalStatus'] !== undefined && q['approvalStatus'] !== '') {
      const s = q['approvalStatus'];
      if (typeof s !== 'string' || !STATUSES.includes(s)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '결재 상태 값이 올바르지 않습니다.');
      }
      approvalStatus = s;
    }
    return transaction(async (db) => {
      const where = `(CAST(:projectId AS bigint) IS NULL OR project_id = CAST(:projectId AS bigint))
        AND (CAST(:approvalStatus AS text) IS NULL OR approval_status = CAST(:approvalStatus AS text))`;
      const counts = await db.query(
        `SELECT COUNT(*) AS total FROM purchase_request WHERE ${where}`,
        { projectId, approvalStatus },
      );
      const items = await db.query(
        `SELECT purchase_request_id AS "purchaseRequestId", document_no AS "documentNo", title,
                amount, approval_status AS "approvalStatus"
           FROM purchase_request
          WHERE ${where}
          ORDER BY purchase_request_id DESC
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { projectId, approvalStatus, size, offset: page * size },
      );
      return {
        items: items.map((r: any) => ({ ...r, amount: Number(r.amount) })),
        page,
        size,
        total: Number(counts[0].total),
      };
    });
  }

  @Post('/purchase-requests/:purchaseRequestId/submit')
  @HttpCode(200)
  async submitPurchaseRequest(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = toInt(req.params['purchaseRequestId']);
    if (id === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '품의서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT purchase_request_id AS "id", document_no AS "documentNo", title,
                project_id AS "projectId", budget_item_id AS "budgetItemId",
                amount, approval_status AS "approvalStatus"
           FROM purchase_request
          WHERE purchase_request_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'PURCHASE_REQUEST_NOT_FOUND', '품의서를 찾을 수 없습니다.');
      }
      const pr = found[0];
      if (pr.approvalStatus !== '기안') {
        throw new ApiError(409, 'PURCHASE_REQUEST_STATUS_CONFLICT', '상신할 수 있는 상태가 아닙니다.');
      }
      const balance = await balanceOf(db, Number(pr.projectId), Number(pr.budgetItemId));
      if (Number(pr.amount) > balance) {
        throw new ApiError(422, 'AMOUNT_EXCEEDS_BUDGET_BALANCE', '품의 금액이 예산잔액을 초과했습니다.');
      }
      const forms = await db.query(
        `SELECT approval_form_id AS "formId" FROM approval_form
          WHERE use_status = '사용' AND is_linked_approval = true
          ORDER BY approval_form_id LIMIT 1`,
        {},
      );
      const emps = await db.query(
        'SELECT department_id AS "departmentId" FROM employee WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      if (forms.length === 0 || emps.length === 0 || emps[0].departmentId === null) {
        throw new ApiError(502, 'APPROVAL_LINKAGE_FAILED', '전자결재 연계에 실패했습니다.');
      }
      const docs = await db.query(
        `INSERT INTO approval_document (
           approval_form_id, drafter_id, drafter_department_id, document_number, title,
           approval_status, is_urgent, is_secret, linked_business_type, linked_business_id,
           submitted_at, created_at, updated_at
         ) VALUES (
           CAST(:formId AS bigint), CAST(:userId AS bigint), CAST(:departmentId AS bigint),
           :documentNo, :title, '결재대기', false, false, :linkedType, CAST(:id AS bigint),
           now(), now(), now()
         ) RETURNING approval_document_id AS "approvalDocumentId"`,
        {
          formId: forms[0].formId,
          userId: user.id,
          departmentId: emps[0].departmentId,
          documentNo: pr.documentNo,
          title: pr.title,
          linkedType: LINKED_TYPE,
          id,
        },
      );
      const rows = await db.query(
        `UPDATE purchase_request
            SET approval_status = '결재대기',
                approval_document_id = CAST(:documentId AS bigint),
                updated_at = now()
          WHERE purchase_request_id = CAST(:id AS bigint)
          RETURNING approval_status AS "approvalStatus"`,
        { documentId: docs[0].approvalDocumentId, id },
      );
      return rows[0];
    });
  }

  @Get('/budget-statuses')
  async listBudgetStatuses(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원', '예산·회계 담당자');
    const q = checks.queryOf(req.query);
    const { page, size } = pageParams(q);
    const projectId = toInt(q['projectId']);
    if (projectId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '프로젝트를 선택하세요.');
    }
    let budgetItemId: number | null = null;
    if (q['budgetItemId'] !== undefined && q['budgetItemId'] !== '') {
      budgetItemId = toInt(q['budgetItemId']);
      if (budgetItemId === null) {
        throw new ApiError(400, 'VALIDATION_FAILED', '예산과목 값이 올바르지 않습니다.');
      }
    }
    return transaction(async (db) => {
      const scope = `b.budget_item_id IN (
          SELECT budget_item_id FROM main_budget WHERE project_id = CAST(:projectId AS bigint)
          UNION
          SELECT budget_item_id FROM budget_carryover WHERE project_id = CAST(:projectId AS bigint)
        )
        AND (CAST(:budgetItemId AS bigint) IS NULL OR b.budget_item_id = CAST(:budgetItemId AS bigint))`;
      const counts = await db.query(
        `SELECT COUNT(*) AS total FROM budget_item b WHERE ${scope}`,
        { projectId, budgetItemId },
      );
      const rows = await db.query(
        `SELECT b.budget_item_id AS "budgetItemId",
           COALESCE((SELECT SUM(e.amount) FROM exec_budget e
             JOIN main_budget m ON m.main_budget_id = e.main_budget_id
             WHERE m.project_id = CAST(:projectId AS bigint)
               AND m.budget_item_id = b.budget_item_id), 0) AS "execBudgetAmount",
           COALESCE((SELECT SUM(c.carryover_amount) FROM budget_carryover c
             WHERE c.project_id = CAST(:projectId AS bigint)
               AND c.budget_item_id = b.budget_item_id), 0) AS "carryoverAmount",
           COALESCE((SELECT SUM(p.amount) FROM purchase_request p
             WHERE p.project_id = CAST(:projectId AS bigint)
               AND p.budget_item_id = b.budget_item_id
               AND p.approval_status IN ('결재대기', '진행중', '승인', '완료')), 0) AS "executedAmount"
           FROM budget_item b
          WHERE ${scope}
          ORDER BY b.budget_item_id
          LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { projectId, budgetItemId, size, offset: page * size },
      );
      const items = rows.map((r: any) => {
        const exec = Number(r.execBudgetAmount);
        const carry = Number(r.carryoverAmount);
        const executed = Number(r.executedAmount);
        return {
          budgetItemId: Number(r.budgetItemId),
          execBudgetAmount: exec,
          carryoverAmount: carry,
          totalBudgetAmount: exec + carry,
          executedAmount: executed,
          balanceAmount: exec + carry - executed,
        };
      });
      return { items, page, size, total: Number(counts[0].total) };
    });
  }
}

