import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  ErrorText,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Select,
  TextInput,
  Tiles,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

const TYPE_OPTIONS: [string, string][] = [
  ['지출', '지출'],
  ['구매', '구매'],
];

const SIZE = 20;

function BudgetBox({ role, projectId, budgetItemId }: { role: string; projectId: unknown; budgetItemId?: unknown }) {
  const { data, error } = useData<Page | undefined>(async () => {
    if (!projectId) return undefined;
    return call<Page>('GET', '/budget-statuses', role, undefined, { projectId, budgetItemId, size: 50 });
  }, [projectId, budgetItemId]);
  if (!projectId) return <p>프로젝트를 선택하면 예산 현황이 보입니다.</p>;
  if (error) return <ErrorText text={error} />;
  return (
    <DataTable
      rows={data ? data.items : []}
      empty='예산 현황이 없습니다.'
      columns={[
        { key: 'budgetItemId', label: '예산과목', render: (r: Row) => <RefName table='budget_item' role={role} value={r.budgetItemId} /> },
        { key: 'execBudgetAmount', label: '실행예산액', render: (r: Row) => <Num value={r.execBudgetAmount} /> },
        { key: 'carryoverAmount', label: '이월예산액', render: (r: Row) => <Num value={r.carryoverAmount} /> },
        { key: 'totalBudgetAmount', label: '예산총액', render: (r: Row) => <Num value={r.totalBudgetAmount} /> },
        { key: 'executedAmount', label: '집행액', render: (r: Row) => <Num value={r.executedAmount} /> },
        { key: 'balanceAmount', label: '예산잔액', render: (r: Row) => <Num value={r.balanceAmount} /> },
      ]}
    />
  );
}

export default function FnSfr00401Page({ role, notify }: PageProps) {
  const [projectDraft, setProjectDraft] = useState<number | string>('');
  const [statusDraft, setStatusDraft] = useState('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [status, setStatus] = useState('');
  const [pageNo, setPageNo] = useState(0);
  const [creating, setCreating] = useState(false);
  const [submitting, setSubmitting] = useState<Row | null>(null);
  const [title, setTitle] = useState('');
  const [requestType, setRequestType] = useState('');
  const [formProject, setFormProject] = useState<number | string>('');
  const [formItem, setFormItem] = useState<number | string>('');
  const [amount, setAmount] = useState<number | string>('');
  const [reason, setReason] = useState('');
  const [inspection, setInspection] = useState('');

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/purchase-requests', role, undefined, { projectId, approvalStatus: status, page: pageNo, size: SIZE }),
    [projectId, status, pageNo],
  );
  const rows = data ? data.items : [];
  const draftCount = rows.filter((r) => r.approvalStatus === '기안').length;

  function openCreate() {
    setTitle('');
    setRequestType('');
    setFormProject('');
    setFormItem('');
    setAmount('');
    setReason('');
    setInspection('');
    setCreating(true);
  }

  async function create() {
    if (title.trim() === '') throw new Error('품의 제목을 입력하세요.');
    if (requestType === '') throw new Error('품의 유형을 선택하세요.');
    if (formProject === '') throw new Error('프로젝트를 선택하세요.');
    if (formItem === '') throw new Error('예산과목을 선택하세요.');
    if (amount === '') throw new Error('품의 금액을 입력하세요.');
    if (reason.trim() === '') throw new Error('품의 사유를 입력하세요.');
    await call('POST', '/purchase-requests', role, {
      title,
      requestType,
      projectId: formProject,
      budgetItemId: formItem,
      amount,
      reason,
      assetInspectionRequired: inspection === 'true',
    });
    notify('품의서를 등록했습니다.');
    setCreating(false);
    reload();
  }

  async function submit() {
    if (!submitting) return;
    await call('POST', '/purchase-requests/' + submitting.purchaseRequestId + '/submit', role, {});
    notify('결재를 상신했습니다.');
    setSubmitting(null);
    reload();
  }

  return (
    <div className='bento'>
      <section className='box span-12'>
        <h2>품의 현황</h2>
        <Tiles
          items={[
            ['조회 건수', <Num value={data ? data.total : 0} />],
            ['기안 상태(현재 쪽)', <Num value={draftCount} />],
          ]}
        />
      </section>
      <section className='box span-8'>
        <h2>품의 목록</h2>
        <Filters
          onSearch={() => {
            setProjectId(projectDraft);
            setStatus(statusDraft);
            setPageNo(0);
          }}
          onReset={() => {
            setProjectDraft('');
            setStatusDraft('');
            setProjectId('');
            setStatus('');
            setPageNo(0);
          }}
        >
          <Field label='프로젝트'>
            <LookupSelect table='project' role={role} value={projectDraft} onChange={setProjectDraft} />
          </Field>
          <Field label='결재 상태'>
            <Select value={statusDraft} onChange={setStatusDraft} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type='button' onClick={openCreate}>품의서 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          empty='품의서가 없습니다.'
          columns={[
            { key: 'documentNo', label: '문서번호' },
            { key: 'title', label: '품의 제목' },
            { key: 'amount', label: '품의 금액', render: (r: Row) => <Num value={r.amount} /> },
            { key: 'approvalStatus', label: '결재 상태', render: (r: Row) => <Badge value={r.approvalStatus} /> },
            {
              key: 'action',
              label: '처리',
              render: (r: Row) =>
                r.approvalStatus === '기안' ? (
                  <button type='button' onClick={() => setSubmitting(r)}>상신</button>
                ) : null,
            },
          ]}
        />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      <section className='box span-4'>
        <h2>예산 현황</h2>
        <BudgetBox role={role} projectId={projectId} />
      </section>
      {creating ? (
        <Drawer title='품의서 등록' onClose={() => setCreating(false)}>
          <Form onSubmit={create} submit='저장'>
            <Field label='품의 제목' required wide>
              <TextInput value={title} onChange={setTitle} />
            </Field>
            <Field label='품의 유형' required>
              <Select value={requestType} onChange={setRequestType} options={TYPE_OPTIONS} />
            </Field>
            <Field label='프로젝트' required>
              <LookupSelect table='project' role={role} value={formProject} onChange={setFormProject} />
            </Field>
            <Field label='예산과목' required>
              <LookupSelect table='budget_item' role={role} value={formItem} onChange={setFormItem} />
            </Field>
            <Field label='품의 금액' required>
              <NumberInput value={amount} onChange={setAmount} />
            </Field>
            <Field label='자산 검수 여부'>
              <Select
                value={inspection}
                onChange={setInspection}
                options={[['true', '검수 필요'], ['false', '검수 불필요']]}
                placeholder='선택 안 함'
              />
            </Field>
            <Field label='품의 사유' required wide>
              <TextInput value={reason} onChange={setReason} multiline />
            </Field>
          </Form>
          <h2>선택한 예산과목 현황</h2>
          <BudgetBox role={role} projectId={formProject} budgetItemId={formItem} />
        </Drawer>
      ) : null}
      {submitting ? (
        <Drawer title='결재 상신' onClose={() => setSubmitting(null)}>
          <Pairs
            items={[
              ['문서번호', String(submitting.documentNo ?? '')],
              ['품의 제목', String(submitting.title ?? '')],
              ['품의 금액', <Num value={submitting.amount} />],
            ]}
          />
          <Form onSubmit={submit} submit='상신' note='상신하면 전자결재로 넘어가며 수정할 수 없습니다.' />
        </Drawer>
      ) : null}
    </div>
  );
}
